import widgetCardStylesText from '../widget-card.css?inline';
import { cssStyleSheet } from '../../../utils/css.js';
import { navigate } from '../../../router.js';
import { createWidgetStatusMixin } from '../../_shared/widget-status.js';
import { createComponentLogger } from '../../../utils/component-logger.js';
import { safeExec } from '../../../utils/safe-exec.js';
import { AiService } from '../../../services/ai.service.js';
import { localAiLabel } from '../../ai/local-ai-label.js';
import type { LocalAiState } from '@motivation/shared';

const widgetCardStyles = cssStyleSheet(widgetCardStylesText);
const log = createComponentLogger('home/ai-summary-widget');
const TICK_MS = 15_000;

const template = document.createElement('template');
template.innerHTML = `
    <div class="widget-header">
        <h2 class="widget-title">AI</h2>
    </div>
    <p class="widget-body" id="local-ai"></p>
`;

/** Story 426: whether Local AI is on, and its time left or "kept on". Tapping opens the AI section. */
export class AiSummaryWidget extends HTMLElement {
    private status!: ReturnType<typeof createWidgetStatusMixin>;
    private state: LocalAiState | null = null;
    private ticker: ReturnType<typeof setInterval> | null = null;

    constructor() {
        super();
        this.attachShadow({ mode: 'open' });
        this.status = createWidgetStatusMixin(this);
        this.shadowRoot!.adoptedStyleSheets = [widgetCardStyles];
        this.shadowRoot!.appendChild(template.content.cloneNode(true));
        this.style.setProperty('--widget-color', 'var(--color-ai, #27ae60)');
        this.addEventListener('click', () => navigate('/ai'));
    }

    setLoading() { this.status.setLoading(); }
    setError(err: unknown) { this.status.setError(err); }
    clearStatus() { this.status.clearStatus(); }

    connectedCallback() {
        this.refresh();
        this.ticker = setInterval(() => this.render(), TICK_MS);
    }

    disconnectedCallback() {
        if (this.ticker) clearInterval(this.ticker);
        this.ticker = null;
    }

    async refresh() {
        await safeExec(this, log, async () => {
            this.state = await AiService.getLocalAi();
            this.render();
        });
    }

    private render() {
        if (!this.state) return;
        this.shadowRoot!.getElementById('local-ai')!.textContent = `Local AI: ${localAiLabel(this.state, Temporal.Now.instant())}`;
    }
}

if (!customElements.get('ai-summary-widget')) {
    customElements.define('ai-summary-widget', AiSummaryWidget);
}
